import {
  type TableValue
} from '@Pimcore/modules/element/dynamic-types/definitions/objects/data-related/components/table/hooks/use-table-value'

export const getCopyData = (value: TableValue | null): string => {
  if (value === null) {
    return ''
  }

  return value.map(row => Array.isArray(row) ? row.join('\t') : Object.values(row).join('\t')).join('\n')
}

export const getPasteData = (data: string): TableValue => {
  return data.split('\n').map(row => row.split('\t'))
}
